INSERT INTO TEMPLATE (ID,COMPANYID,"KEY",DESCRIPTION,SUBJECT,"BODY",EMAILTO,MASTERTEMPLATEID,UPDATEUSERCODE,UPDATEDATE) VALUES (7,0,'Notify_2FA','Envio de OTP por 2FA','Asistencia para iniciar sesión a la zona de aliados','<p>En cumplimiento de nuestro compromiso con la seguridad, hemos implementado la autenticación de dos factores (2FA) en su cuenta. Para continuar con el proceso, utilice el siguiente código de verificación: {Data.User.OneTimePassword}</p>',NULL,NULL,78,TIMESTAMP'1970-02-07 00:00:00');
